package io.heapy.kotdoc.crypto

import kotlinx.serialization.json.*
import org.junit.jupiter.api.Assertions.*
import org.junit.jupiter.api.DynamicTest
import org.junit.jupiter.api.TestFactory
import java.io.File
import java.security.MessageDigest
import java.util.stream.Stream
import java.util.zip.GZIPInputStream

/** Expectations are generated by the independently compiled pinned C, never by this observer. */
class CryptoP256WordsTest {
    private fun JsonObject.text(key: String) = getValue(key).jsonPrimitive.content
    private fun JsonObject.int(key: String) = text(key).toInt()
    private fun words(hex: String, bits: Int): LongArray = hex.chunked(bits / 4).reversed().map { it.toULong(16).toLong() }.toLongArray()
    private fun hex(region: CryptoP256Words.Region, n: Int, bits: Int) = (n-1 downTo 0).joinToString("") { region[it].toULong().toString(16).padStart(bits/4,'0') }
    private fun observe(r: JsonObject): JsonObject {
        val bits=r.int("bits"); val engine=CryptoP256Words(bits);val n=engine.digits
        val guard=if(bits==32) 0x695a4b3cL else 0xa5968778695a4b3cuL.toLong()
        class Buffer(value: String) {
            val data=longArrayOf(guard)+words(value,bits)+longArrayOf(guard)
            val region=CryptoP256Words.Region(data,1)
            fun guarded()=data.first()==guard && data.last()==guard
        }
        val a=Buffer(r.text("a"));val b=Buffer(r.text("b"));val m=Buffer(r.text("m"));val c=Buffer("a5".repeat(32))
        val alias=r.int("alias"); val out=when(alias){1->a.region;2->b.region;3->m.region;else->c.region}
        val op=r.text("op");val shift=r.int("shift"); val audit=CryptoP256Words.Audit(if(op=="inv") shift else 0)
        val top=r.text("top").toULong().toLong();val mask=r.text("mask").toULong().toLong()
        val binary=ByteArray(36){0xa5.toByte()};val span=CryptoByteSpan(binary,2,32)
        var ret=0L
        when(op) {
            "init"->engine.init(out,audit)
            "clear"->engine.clear(out,audit)
            "bit"->ret=engine.bit(a.region,shift,audit).toLong()
            "zero"->ret=if(engine.zero(a.region,audit))1 else 0
            "odd"->ret=if(engine.odd(a.region,audit))1 else 0
            "even"->ret=if(engine.even(a.region,audit))1 else 0
            "muladd"->ret=engine.mulAdd(a.region,top,mask,out,audit)
            "subtop"->ret=engine.subTop(top,a.region,mask,out,audit)
            "subm"->ret=engine.subM(m.region,top,out,mask,audit)
            "addm"->ret=engine.addM(m.region,top,out,mask,audit)
            "shl"->ret=engine.shiftLeft(a.region,shift,out,audit)
            "shr"->engine.shiftRight(a.region,shift,out,audit)
            "shr1"->engine.shiftRightOne(a.region,shift,out,audit)
            "cmp"->ret=engine.cmp(a.region,b.region,audit).toLong()
            "sub"->ret=engine.sub(a.region,b.region,if(alias==4)null else out,audit).toLong()
            "add"->ret=engine.add(a.region,b.region,if(alias==4)null else out,audit).toLong()
            "addd"->ret=engine.addDigit(a.region,top,if(alias==4)null else out,audit).toLong()
            "mod"->engine.mod(m.region,a.region,out,audit)
            "mul"->engine.modMul(m.region,a.region,top,b.region,out,audit)
            "inv"->try {engine.inverseVarTime(m.region,a.region,out,audit)} catch(_:CryptoP256Words.ObservationStopped) { }
            "valid"->ret=if(engine.valid(a.region,b.region,audit))1 else 0
            "from"->{r.text("a").chunked(2).forEachIndexed { i,s->span[i]=s.toInt(16).toByte() };engine.fromBinary(span,out,audit)}
            "to"->engine.toBinary(a.region,span,audit)
            "modadd"->engine.modAdd(m.region,a.region,b.region,out,audit)
            "modsub"->engine.modSub(m.region,a.region,b.region,out,audit)
            "mont"->engine.montMul(a.region,b.region,out,audit)
            "safe"->engine.inverseSafe(a.region,out,audit)
            "n"->out.copyFrom(engine.n,n)
            "p"->out.copyFrom(engine.p,n)
            "b"->out.copyFrom(engine.b,n)
            "r2"->out.copyFrom(engine.r2,n)
            "one"->out.copyFrom(engine.one,n)
            else->error(op)
        }
        return buildJsonObject {
            put("ret",ret.toULong().toString());put("a",hex(a.region,n,bits));put("b",hex(b.region,n,bits));put("m",hex(m.region,n,bits));put("c",hex(c.region,n,bits))
            put("binary",binary.joinToString(""){(it.toInt() and 255).toString(16).padStart(2,'0')})
            put("guards",listOf(a,b,m,c).all{it.guarded()})
            put("ops",JsonArray(audit.ops.map{JsonPrimitive(it.toString())}));put("corrections",audit.quotientCorrections);put("stopped",audit.stopped)
            put("state",JsonArray(if(audit.stopped)(0..<4).map{JsonPrimitive(hex(CryptoP256Words.Region(audit.inverseState,it*n),n,bits))}else emptyList()))
        }
    }
    @TestFactory
    fun originalWordObservations(): Stream<DynamicTest> {
        val root=File(System.getProperty("kotdoc.root"))
        val lines=GZIPInputStream(javaClass.getResourceAsStream("/crypto-p256-words/data.jsonl.gz")!!).bufferedReader().use{it.readLines()}
        val manifest=Json.parseToJsonElement(lines.first()).jsonObject
        val tests=mutableListOf<DynamicTest>()
        for((path,expected)in manifest.getValue("sources").jsonObject) tests+=DynamicTest.dynamicTest("source $path") {
            val digest=MessageDigest.getInstance("SHA-256").digest(File(root,path).readBytes()).joinToString(""){(it.toInt() and 255).toString(16).padStart(2,'0')}
            assertEquals(expected.jsonPrimitive.content,digest,path)
        }
        assertEquals(manifest.int("cases"),lines.size-1)
        for((index,line)in lines.drop(1).withIndex()) {
            val c=Json.parseToJsonElement(line).jsonObject;val r=c.getValue("request").jsonObject
            tests+=DynamicTest.dynamicTest("$index ${r.text("bits")} ${r.text("op")} ${c.text("group")}") {assertEquals(c.getValue("expected"),observe(r),r.toString())}
        }
        return tests.stream()
    }
}
